css:
:scope { width: min(100%, 980px); margin-inline: auto; }
.gx { display: grid; grid-template-columns: repeat(24, minmax(0, 1fr)); grid-auto-rows: minmax(8px, auto); column-gap: 0; }
.gx__i { position: relative; z-index: 1; margin: 0; min-width: 0; overflow-wrap: break-word; }
.gx__i p { margin: 0; }
.gx__p { z-index: 0; }
.gx__img picture, .gx__img img { display: block; width: 100%; height: 100%; object-fit: cover; }
.gx__p1 { grid-column: 1 / span 24; grid-row: 1 / span 124; background: var(--os-color-background);  border-radius: 0px; }
.gx__i2 { grid-column: 5 / span 14; grid-row: 5 / span 8; font-family: var(--os-font-label); font-size: 50px; font-weight: 400; line-height: 1.2; letter-spacing: 0em; text-align: center; color: inherit; }
.gx__i3 { grid-column: 1 / span 22; grid-row: 15 / span 10; font-family: var(--os-font-body); font-size: 10px; font-weight: 400; line-height: 1.2; letter-spacing: 0em; color: var(--os-color-background); }
.gx__i4 { grid-column: 1 / span 22; grid-row: 25 / span 3; font-family: var(--os-font-body); font-size: 16px; font-weight: 400; line-height: 1.5; letter-spacing: 0em; color: var(--os-color-heading); }
.gx__i5 { grid-column: 1 / span 22; grid-row: 31 / span 3; font-family: var(--os-font-body); font-size: 16px; font-weight: 400; line-height: 1.5; letter-spacing: 0em; color: var(--os-color-heading); }
.gx__i6 { grid-column: 1 / span 22; grid-row: 46 / span 10; font-family: var(--os-font-body); font-size: 10px; font-weight: 400; line-height: 1.2; letter-spacing: 0em; color: var(--os-color-background); }
.gx__i7 { grid-column: 1 / span 22; grid-row: 58 / span 10; font-family: var(--os-font-body); font-size: 10px; font-weight: 400; line-height: 1.2; letter-spacing: 0em; color: var(--os-color-background); }
.gx__i8 { grid-column: 1 / span 22; grid-row: 71 / span 10; font-family: var(--os-font-body); font-size: 10px; font-weight: 400; line-height: 1.2; letter-spacing: 0em; color: var(--os-color-background); }
.gx__i9 { grid-column: 1 / span 22; grid-row: 84 / span 10; font-family: var(--os-font-body); font-size: 10px; font-weight: 400; line-height: 1.2; letter-spacing: 0em; color: var(--os-color-background); }
.gx__i10 { grid-column: 1 / span 22; grid-row: 97 / span 10; font-family: var(--os-font-body); font-size: 10px; font-weight: 400; line-height: 1.2; letter-spacing: 0em; color: var(--os-color-background); }
.gx__i11 { grid-column: 1 / span 22; grid-row: 109 / span 10; font-family: var(--os-font-body); font-size: 10px; font-weight: 400; line-height: 1.2; letter-spacing: 0em; color: var(--os-color-background); }
@media (max-width: 767px) {
  .gx { display: flex; flex-direction: column; gap: var(--os-space-sm); }
  .gx__p1 { display: none; }
  .gx__i2 { font-family: var(--os-font-label); font-size: 40px; }
  .gx__i3 { font-family: var(--os-font-body); font-size: 14px; }
  .gx__i4 { font-family: var(--os-font-body); font-size: 14px; }
  .gx__i5 { font-family: var(--os-font-body); font-size: 14px; }
  .gx__i6 { font-family: var(--os-font-body); font-size: 14px; }
  .gx__i7 { font-family: var(--os-font-body); font-size: 14px; }
  .gx__i8 { font-family: var(--os-font-body); font-size: 14px; }
  .gx__i9 { font-family: var(--os-font-body); font-size: 14px; }
  .gx__i10 { font-family: var(--os-font-body); font-size: 14px; }
  .gx__i11 { font-family: var(--os-font-body); font-size: 14px; }
}
